import{_ as l,a0 as r,w as p,s as a,ao as i,I as e,x as s,a1 as n,A as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標 | LCTT x X-CMD","titleTemplate":false,"description":"簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop","title":"簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標","tag":"202309","desc":""},"relativePath":"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop.md","filePath":"[post].md"}'),d={name:"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop.md"};function b(m,t,g,f,k,h){const o=r("Link");return p(),a("div",null,[t[22]||(t[22]=i('<h1 id="簡單技巧-從-ubuntu-桌面上刪除主文件夾圖標" tabindex="-1">簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標 <a class="header-anchor" href="#簡單技巧-從-ubuntu-桌面上刪除主文件夾圖標" aria-label="Permalink to “簡單技巧：從 Ubuntu 桌面上刪除主文件夾圖標”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/02/153353a01ouhl1a5svhym0.jpg" alt=""></p><blockquote><p>對於不想在桌面上看到主文件夾圖標的 Ubuntu 用户，這裏有一個簡單技巧。</p></blockquote><p>Ubuntu 使用定製的 GNOME 版本，由於側邊啓動器，它的外觀與舊的 Unity 桌面有些相似。</p><p>普通 GNOME 和 Ubuntu 的 GNOME 之間的另一個區別是桌面上主文件夾和回收站的使用。這些圖標就在那裏，以便你可以快速訪問它們。</p><p><img src="https://itsfoss.com/content/images/2023/08/home-folder-icon-on-ubuntu-desktop.png" alt="Home folder icon on Ubuntu desktop"></p><p>如果你覺得不美觀，可以從桌面視圖中刪除主文件夾。</p><p>讓我分享一下 GUI 和命令列方法。</p><h3 id="在-ubuntu-中隱藏桌面上的主文件夾圖標" tabindex="-1">在 Ubuntu 中隱藏桌面上的主文件夾圖標 <a class="header-anchor" href="#在-ubuntu-中隱藏桌面上的主文件夾圖標" aria-label="Permalink to “在 Ubuntu 中隱藏桌面上的主文件夾圖標”">​</a></h3><p>你只需要這樣做：</p>',10)),e("p",null,[e("strong",null,[t[1]||(t[1]=s("在 Ubuntu 中按 ",-1)),t[2]||(t[2]=e("code",null,"Super + D",-1)),t[3]||(t[3]=s()),n(o,{href:"https://itsfoss.com/ubuntu-shortcuts/"},{default:u(()=>[...t[0]||(t[0]=[s("鍵盤快捷鍵",-1)])]),_:1}),t[4]||(t[4]=s("訪問桌面",-1))]),t[5]||(t[5]=s("。",-1))]),t[23]||(t[23]=i('<p>現在<strong>右鍵單擊桌面上的空白區域</strong>。</p><p>從右鍵單擊上下文菜單中，<strong>選擇<ruby>桌面圖標設置<rt>Desktop Icons Settings</rt></ruby></strong>。</p><p><img src="https://itsfoss.com/content/images/2023/08/access-ubuntu-desktop-icon-settings.png" alt="Right click on the desktop and click the Desktop Icons Settings"></p><p>它將在“<ruby>設置<rt>Settings</rt></ruby>”應用中打開 <ruby>Ubuntu 桌面<rt>Ubuntu Desktop</rt></ruby>設置選項。你也可以通過打開“設置”應用並轉到側邊欄中的“Ubuntu 桌面”選項來訪問它。</p><p>在這裏，你將看到<strong><ruby>顯示個人文件夾<rt>Show Personal folder</rt></ruby>的切換選項</strong>。將其關閉以禁用桌面上的主文件夾圖標。</p><p><img src="https://itsfoss.com/content/images/2023/08/disable-home-folder-icon-on-ubuntu-desktop.png" alt="Disable the Show Personal folder button"></p><blockquote><p>💡 想要恢復主文件夾圖標嗎？ 再次切換它。</p></blockquote><h3 id="使用命令列禁用主文件夾圖標" tabindex="-1">使用命令列禁用主文件夾圖標 <a class="header-anchor" href="#使用命令列禁用主文件夾圖標" aria-label="Permalink to “使用命令列禁用主文件夾圖標”">​</a></h3><p>是的，你可以從命令列完全禁用主文件夾圖標。</p><p>打開終端並使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.ding show-home false</span></span></code></pre></div><p>效果將是立竿見影的。</p><p>要恢復圖標，請使用相同的命令，但使用 <code>true</code> 而不是 <code>false</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.ding show-home true</span></span></code></pre></div><p>看到那有多簡單了嗎？ 也可以採取類似的步驟來刪除回收站圖標。</p>',15)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://itsfoss.com/remove-trash-icon-ubuntu-desktop/"},{default:u(()=>[...t[6]||(t[6]=[s("如何在 Ubuntu 中移走桌面的回收站圖標",-1)])]),_:1})])])]),t[24]||(t[24]=e("p",null,[e("em",null,"（題圖：MJ/84c2e427-a8b3-40b7-a753-22f020800242）")],-1)),t[25]||(t[25]=e("hr",null,null,-1)),e("p",null,[t[8]||(t[8]=s("via: ",-1)),n(o,{href:"https://itsfoss.com/ubuntu-remove-home-icon/"},{default:u(()=>[...t[7]||(t[7]=[s("https://itsfoss.com/ubuntu-remove-home-icon/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=s("作者：",-1)),n(o,{href:"https://itsfoss.com/author/abhishek/"},{default:u(()=>[...t[9]||(t[9]=[s("Abhishek Prakash",-1)])]),_:1}),t[14]||(t[14]=s(" 選題：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[10]||(t[10]=[s("lujun9972",-1)])]),_:1}),t[15]||(t[15]=s(" 譯者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:u(()=>[...t[11]||(t[11]=[s("geekpi",-1)])]),_:1}),t[16]||(t[16]=s(" 校對：",-1)),n(o,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:u(()=>[...t[12]||(t[12]=[s("校對者ID",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=s("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[17]||(t[17]=[s("LCTT",-1)])]),_:1}),t[20]||(t[20]=s(" 原創編譯，",-1)),n(o,{href:"https://linux.cn/"},{default:u(()=>[...t[18]||(t[18]=[s("Linux中國",-1)])]),_:1}),t[21]||(t[21]=s(" 榮譽推出",-1))])])}const x=l(d,[["render",b]]);export{C as __pageData,x as default};
